save(315,dict(paragraphs=["Prafulla K. Panda, also published as Prafulla Kumar Panda, is an Odisha poet and lecturer. He is the author of Bounty of Silence: Verses Unveiling the Songs of Soul and editor of the anthology Beyond the Horizon. In an interview, he describes writing as a patient process of observing everyday experience and finding words for feeling.","His poems here combine rhyme with direct reflection on responsibility and imagination. ‘Character Is Destiny’ and ‘Work for The Luck’ turn attention from fate toward action. ‘He Too Be Called A Poet’ offers a complementary generosity: the attentive reader, able to preserve beauty and respond to another person’s words, shares in the poet’s work."],sources=[source('The Mt. Kenya Times — Prafulla Kumar Panda interview, November 2024','https://mountkenyatimes.co.ke/wp-content/uploads/2024/11/November-16-17-2024-Mt-Kenya-Times-ePAPER.pdf',['Author interview confirms Odisha lecturer, Bounty of Silence authorship, Beyond the Horizon editorship and process of observation/thought/words.']),source('AllPoetry — Prafulla Kumar Panda author profile','https://allpoetry.com/Prafulla_Kumar_Panda',['Full Bounty of Silence subtitle, anthology editorship and Khaira/Balasore origin match capture.'],'search_index_excerpt')],books=[],identity_match='Full name, lecturer profession, two distinctive book titles and Khaira/Balasore origin match capture.',poems_read=[dict(id=561,title='Work for The Luck',basis='Full English original read; karma, effort, proverbial shoe and Cinderella imagery.'),dict(id=465,title='Character Is Destiny',basis='Full English original read; stars contrasted with personal responsibility.'),dict(id=387,title='He Too Be Called A Poet',basis='Full English original read; imaginative writer and reader as parallel makers of beauty.')],limitations=['No verifiable dedicated publisher/book-edition link found; titles supported by author interview but no invented purchase URLs.','Numerous online awards and honorific claims not independently verified and omitted.','Author profile says two collections while listing three; totals omitted.','Moral claims belong to poems; not presented as universal factual explanations of misfortune.'],research_leads=[dict(url='https://www.poemhunter.com/prafulla-kumar-panda/',access='search_index_excerpt',finding='Matching locality and book titles; expanded award claims and different collection count not imported.')],next_action='Author/editor to provide edition details and review draft.'))
